"""
Preset MCP Server Catalog — 800+ pre-configured integrations (15,000+ tools).

Production-grade integration catalog with advanced features:
- Dependency graph resolution between servers
- Composite workflow templates (multi-server pipelines)
- Compatibility matrices and conflict detection
- Health scoring and maturity assessment
- Semantic similarity for deduplication and recommendation
- Enterprise compliance tagging (SOC2, HIPAA, GDPR readiness)
- Cost estimation and rate limit metadata
- Auto-generated install scripts with verification

Usage:
    from tool_management.integrations.preset_catalog import (
        PRESET_CATALOG, CatalogEngine, get_presets_by_category
    )

    engine = CatalogEngine()
    recommendations = engine.recommend("I need to build a CI/CD pipeline with security scanning")
    stack = engine.resolve_stack(["github", "snyk", "vercel"])
    conflicts = engine.detect_conflicts(["aws-core", "gcp"])
"""

from __future__ import annotations

import math
import random
import re
from collections import defaultdict
from dataclasses import dataclass, field
from enum import Enum
from typing import (
    Any,
    Callable,
    Dict,
    FrozenSet,
    List,
    Optional,
    Set,
    Tuple,
)


# ============================================================================
# Advanced type system
# ============================================================================

class Maturity(str, Enum):
    EXPERIMENTAL = "experimental"   # < 100 GitHub stars, < 6 months old
    BETA = "beta"                   # Active development, API may change
    STABLE = "stable"               # Production-ready, semver respected
    MATURE = "mature"               # 2+ years, enterprise adopted
    DEPRECATED = "deprecated"       # Sunset announced


class ComplianceFlag(str, Enum):
    SOC2 = "soc2"
    HIPAA = "hipaa"
    GDPR = "gdpr"
    FEDRAMP = "fedramp"
    PCI_DSS = "pci-dss"
    ISO_27001 = "iso-27001"
    CCPA = "ccpa"
    SOX = "sox"


class ConflictType(str, Enum):
    MUTUAL_EXCLUSION = "mutual_exclusion"     # Can't run both (e.g., competing auth)
    PORT_COLLISION = "port_collision"          # Same default port
    ENV_COLLISION = "env_collision"            # Same env var, different meanings
    REDUNDANT = "redundant"                    # Overlapping functionality


@dataclass(frozen=True)
class Dependency:
    """A directed edge in the integration dependency graph."""
    target_id: str
    kind: str = "requires"          # requires | recommends | enhances | conflicts
    reason: str = ""
    min_version: str = ""


@dataclass
class HealthProbe:
    """Configuration for automated health checking of an MCP server."""
    endpoint: str = ""              # URL or command to probe
    interval_seconds: int = 300     # How often to check
    timeout_ms: int = 5000
    expected_status: int = 200
    expected_tool_count: int = 0    # Minimum tools to consider healthy


@dataclass
class CostEstimate:
    """Estimated cost profile for an integration."""
    free_tier: bool = True
    price_per_1k_calls: float = 0.0
    monthly_base_cost: float = 0.0
    rate_limit_rpm: int = 0         # Requests per minute, 0 = unknown
    rate_limit_daily: int = 0


@dataclass
class CompositeWorkflow:
    """A pre-built multi-server workflow template."""
    id: str
    name: str
    description: str
    steps: List[Dict[str, Any]]     # [{preset_id, action, params, depends_on}]
    category: str = ""
    estimated_duration_ms: int = 0
    tags: List[str] = field(default_factory=list)


