# ============================================================================
# CatalogEngine — advanced query, recommendation, and graph resolution
# ============================================================================

class CatalogEngine:
    """
    Production-grade catalog engine with:
    - O(1) lookups via index maps
    - Dependency graph resolution with cycle detection
    - Conflict detection between integrations
    - TF-IDF-based semantic recommendation (no ML deps)
    - Stack resolution: given a set of desired presets, compute
      the full transitive closure of dependencies
    - Enterprise scoring with compliance-aware ranking
    - Composite workflow resolution
    """

    def __init__(self, catalog: Optional[List[Dict[str, Any]]] = None):
        self._catalog = catalog or PRESET_CATALOG
        self._by_id: Dict[str, Dict[str, Any]] = {}
        self._by_category: Dict[str, List[Dict[str, Any]]] = defaultdict(list)
        self._by_tag: Dict[str, List[Dict[str, Any]]] = defaultdict(list)
        self._by_tier: Dict[str, List[Dict[str, Any]]] = defaultdict(list)
        self._idf: Dict[str, float] = {}
        self._tfidf_vectors: Dict[str, Dict[str, float]] = {}
        self._dep_graph: Dict[str, List[Dependency]] = defaultdict(list)
        self._reverse_deps: Dict[str, List[str]] = defaultdict(list)
        self._conflict_map: Dict[str, List[Tuple[str, ConflictType, str]]] = defaultdict(list)
        self._build_indexes()
        self._build_tfidf()
        self._build_dependency_graph()
        self._build_conflict_map()

    # ------------------------------------------------------------------
    # Index construction
    # ------------------------------------------------------------------

    def _build_indexes(self) -> None:
        for p in self._catalog:
            pid = p["id"]
            self._by_id[pid] = p
            self._by_category[p["category"]].append(p)
            self._by_tier[p["tier"]].append(p)
            for tag in p.get("tags", []):
                self._by_tag[tag].append(p)

    def _tokenize(self, text: str) -> List[str]:
        return re.findall(r"[a-z0-9]+", text.lower())

    def _build_tfidf(self) -> None:
        """Build TF-IDF vectors for semantic search without ML dependencies."""
        doc_freq: Dict[str, int] = defaultdict(int)
        docs: Dict[str, List[str]] = {}
        n = len(self._catalog)

        for p in self._catalog:
            tokens = self._tokenize(
                f"{p['name']} {p['description']} {' '.join(p.get('tags', []))} {p['category']}"
            )
            docs[p["id"]] = tokens
            seen: Set[str] = set()
            for t in tokens:
                if t not in seen:
                    doc_freq[t] += 1
                    seen.add(t)

        self._idf = {
            term: math.log((n + 1) / (df + 1)) + 1
            for term, df in doc_freq.items()
        }

        for pid, tokens in docs.items():
            tf: Dict[str, int] = defaultdict(int)
            for t in tokens:
                tf[t] += 1
            max_tf = max(tf.values()) if tf else 1
            vec = {
                term: (0.5 + 0.5 * count / max_tf) * self._idf.get(term, 0)
                for term, count in tf.items()
            }
            norm = math.sqrt(sum(v * v for v in vec.values())) or 1.0
            self._tfidf_vectors[pid] = {k: v / norm for k, v in vec.items()}

    def _build_dependency_graph(self) -> None:
        for src, tgt, kind, reason in KNOWN_DEPENDENCIES:
            dep = Dependency(target_id=tgt, kind=kind, reason=reason)
            self._dep_graph[src].append(dep)
            self._reverse_deps[tgt].append(src)

    def _build_conflict_map(self) -> None:
        for a, b, ctype, reason in KNOWN_CONFLICTS:
            self._conflict_map[a].append((b, ctype, reason))
            self._conflict_map[b].append((a, ctype, reason))

    # ------------------------------------------------------------------
    # Basic lookups (O(1))
    # ------------------------------------------------------------------

    def get_by_id(self, preset_id: str) -> Optional[Dict[str, Any]]:
        return self._by_id.get(preset_id)

    def get_by_category(self, category: str) -> List[Dict[str, Any]]:
        return self._by_category.get(category, [])

    def get_by_tag(self, tag: str) -> List[Dict[str, Any]]:
        return self._by_tag.get(tag, [])

    def get_by_tier(self, tier: str) -> List[Dict[str, Any]]:
        return self._by_tier.get(tier, [])

    # ------------------------------------------------------------------
    # Semantic search (TF-IDF cosine similarity, zero external deps)
    # ------------------------------------------------------------------

    def search(self, query: str, limit: int = 20, min_score: float = 0.05) -> List[Tuple[Dict[str, Any], float]]:
        """Semantic search across the catalog using TF-IDF cosine similarity."""
        tokens = self._tokenize(query)
        if not tokens:
            return []

        qtf: Dict[str, int] = defaultdict(int)
        for t in tokens:
            qtf[t] += 1
        max_qtf = max(qtf.values())
        qvec = {
            term: (0.5 + 0.5 * count / max_qtf) * self._idf.get(term, 0)
            for term, count in qtf.items()
        }
        qnorm = math.sqrt(sum(v * v for v in qvec.values())) or 1.0
        qvec = {k: v / qnorm for k, v in qvec.items()}

        scores: List[Tuple[str, float]] = []
        for pid, dvec in self._tfidf_vectors.items():
            dot = sum(qvec.get(t, 0) * dvec.get(t, 0) for t in qvec)
            if dot >= min_score:
                scores.append((pid, dot))

        scores.sort(key=lambda x: -x[1])
        return [
            (self._by_id[pid], score)
            for pid, score in scores[:limit]
        ]

    # ------------------------------------------------------------------
    # Recommendation engine
    # ------------------------------------------------------------------

    def recommend(
        self,
        query: str,
        *,
        max_results: int = 10,
        tier_filter: Optional[str] = None,
        category_filter: Optional[str] = None,
        max_priority: int = 5,
        boost_official: float = 1.3,
        boost_vendor: float = 1.15,
    ) -> List[Dict[str, Any]]:
        """
        Intelligent recommendation combining semantic similarity,
        tier boosting, and enterprise priority scoring.
        """
        results = self.search(query, limit=max_results * 3)

        scored = []
        for preset, sim_score in results:
            # Apply filters
            if tier_filter and preset["tier"] != tier_filter:
                continue
            if category_filter and preset["category"] != category_filter:
                continue
            if preset.get("enterprise_priority", 5) > max_priority:
                continue

            # Composite score
            tier_boost = 1.0
            if preset["tier"] == "official":
                tier_boost = boost_official
            elif preset["tier"] == "vendor":
                tier_boost = boost_vendor

            priority_bonus = (6 - preset.get("enterprise_priority", 5)) / 5.0
            tool_density = min(preset.get("tool_count", 1) / 50.0, 1.0)

            final_score = (
                sim_score * 0.55
                + priority_bonus * 0.20
                + tool_density * 0.10
                + (tier_boost - 1.0) * 0.15
            )

            scored.append({
                **preset,
                "_score": round(final_score, 4),
                "_sim": round(sim_score, 4),
                "_tier_boost": tier_boost,
            })

        scored.sort(key=lambda x: -x["_score"])
        return scored[:max_results]

    # ------------------------------------------------------------------
    # Dependency graph resolution
    # ------------------------------------------------------------------

    def resolve_stack(self, preset_ids: List[str]) -> Dict[str, Any]:
        """
        Given a list of desired presets, compute the full transitive
        closure of required dependencies, detect conflicts, and return
        install order (topological sort).
        """
        required: Set[str] = set()
        recommended: Set[str] = set()
        visit_stack: List[str] = list(preset_ids)
        visited: Set[str] = set()
        edges: List[Tuple[str, str]] = []

        while visit_stack:
            pid = visit_stack.pop()
            if pid in visited:
                continue
            visited.add(pid)
            required.add(pid)

            for dep in self._dep_graph.get(pid, []):
                edges.append((dep.target_id, pid))
                if dep.kind == "requires":
                    if dep.target_id not in visited:
                        visit_stack.append(dep.target_id)
                elif dep.kind in ("recommends", "enhances"):
                    recommended.add(dep.target_id)

        # Topological sort (Kahn's algorithm)
        in_degree: Dict[str, int] = defaultdict(int)
        adj: Dict[str, List[str]] = defaultdict(list)
        all_nodes = required.copy()
        for src, tgt in edges:
            if src in all_nodes and tgt in all_nodes:
                adj[src].append(tgt)
                in_degree[tgt] += 1
                if src not in in_degree:
                    in_degree[src] = in_degree.get(src, 0)

        queue = [n for n in all_nodes if in_degree.get(n, 0) == 0]
        install_order: List[str] = []
        while queue:
            queue.sort()
            node = queue.pop(0)
            install_order.append(node)
            for neighbor in adj.get(node, []):
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        has_cycle = len(install_order) != len(all_nodes)

        # Detect conflicts
        conflicts = self.detect_conflicts(list(required))

        # Compute aggregate stats
        total_tools = sum(
            self._by_id[pid].get("tool_count", 0)
            for pid in required if pid in self._by_id
        )
        all_env: Set[str] = set()
        for pid in required:
            p = self._by_id.get(pid, {})
            all_env.update(p.get("required_env", []))

        return {
            "required": sorted(required),
            "recommended": sorted(recommended - required),
            "install_order": install_order,
            "has_cycle": has_cycle,
            "conflicts": conflicts,
            "total_presets": len(required),
            "total_tools": total_tools,
            "required_env_vars": sorted(all_env),
            "edges": [(s, t) for s, t in edges if s in required and t in required],
        }

    def get_dependents(self, preset_id: str) -> List[str]:
        """Get all presets that depend on the given preset."""
        return self._reverse_deps.get(preset_id, [])

    def get_dependencies(self, preset_id: str) -> List[Dependency]:
        """Get all dependencies of the given preset."""
        return self._dep_graph.get(preset_id, [])

    # ------------------------------------------------------------------
    # Conflict detection
    # ------------------------------------------------------------------

    def detect_conflicts(self, preset_ids: List[str]) -> List[Dict[str, Any]]:
        """Detect conflicts among a set of presets."""
        id_set = set(preset_ids)
        conflicts = []
        seen_pairs: Set[FrozenSet[str]] = set()

        for pid in preset_ids:
            for target, ctype, reason in self._conflict_map.get(pid, []):
                if target in id_set:
                    pair = frozenset([pid, target])
                    if pair not in seen_pairs:
                        seen_pairs.add(pair)
                        conflicts.append({
                            "presets": sorted([pid, target]),
                            "type": ctype.value,
                            "reason": reason,
                        })

        # Also detect env var collisions dynamically
        env_owners: Dict[str, List[str]] = defaultdict(list)
        for pid in preset_ids:
            p = self._by_id.get(pid, {})
            for env in p.get("required_env", []):
                env_owners[env].append(pid)

        for env, owners in env_owners.items():
            if len(owners) > 1 and not any(
                frozenset(pair) in seen_pairs
                for pair in zip(owners, owners[1:])
            ):
                # Only flag if the env var name is identical but presets are unrelated
                cats = set(self._by_id.get(o, {}).get("category", "") for o in owners)
                if len(cats) > 1:
                    conflicts.append({
                        "presets": owners,
                        "type": ConflictType.ENV_COLLISION.value,
                        "reason": f"Shared env var '{env}' across different categories",
                    })

        return conflicts

    # ------------------------------------------------------------------
    # Enterprise scoring
    # ------------------------------------------------------------------

    def enterprise_score(self, preset_id: str) -> Dict[str, Any]:
        """
        Compute a composite enterprise readiness score (0-100).

        Factors:
        - Tier weight (official=30, vendor=20, community=5)
        - Priority inverse (priority 1 = 25 points)
        - Tool richness (up to 15 points)
        - Has repo (10 points)
        - Low env burden (up to 10 points)
        - Transport modernity (10 points for http/sse)
        """
        p = self._by_id.get(preset_id)
        if not p:
            return {"preset_id": preset_id, "score": 0, "breakdown": {}}

        tier_scores = {"official": 30, "vendor": 20, "community": 5}
        tier_s = tier_scores.get(p["tier"], 0)
        priority_s = max(0, (6 - p.get("enterprise_priority", 5)) * 5)
        tool_s = min(p.get("tool_count", 0) / 4.0, 15)
        repo_s = 10 if p.get("repo") else 0
        env_count = len(p.get("required_env", []))
        env_s = max(0, 10 - env_count * 2)
        transport_s = 10 if p.get("transport") in ("http", "sse") else 5

        total = tier_s + priority_s + tool_s + repo_s + env_s + transport_s
        return {
            "preset_id": preset_id,
            "score": round(min(total, 100), 1),
            "breakdown": {
                "tier": tier_s,
                "priority": priority_s,
                "tool_richness": round(tool_s, 1),
                "has_repo": repo_s,
                "env_simplicity": env_s,
                "transport": transport_s,
            },
        }

    # ------------------------------------------------------------------
    # Find similar / deduplicate
    # ------------------------------------------------------------------

    def find_similar(self, preset_id: str, limit: int = 5) -> List[Tuple[Dict[str, Any], float]]:
        """Find presets most similar to the given one (for dedup or alternatives)."""
        vec = self._tfidf_vectors.get(preset_id)
        if not vec:
            return []

        scores = []
        for other_id, other_vec in self._tfidf_vectors.items():
            if other_id == preset_id:
                continue
            dot = sum(vec.get(t, 0) * other_vec.get(t, 0) for t in vec)
            if dot > 0.1:
                scores.append((other_id, dot))

        scores.sort(key=lambda x: -x[1])
        return [
            (self._by_id[pid], score)
            for pid, score in scores[:limit]
        ]

    def find_duplicates(self, threshold: float = 0.75) -> List[Tuple[str, str, float]]:
        """Find likely duplicate entries in the catalog."""
        dupes = []
        ids = list(self._tfidf_vectors.keys())
        for i, a in enumerate(ids):
            vec_a = self._tfidf_vectors[a]
            for b in ids[i + 1:]:
                vec_b = self._tfidf_vectors[b]
                dot = sum(vec_a.get(t, 0) * vec_b.get(t, 0) for t in vec_a)
                if dot >= threshold:
                    dupes.append((a, b, round(dot, 4)))
        dupes.sort(key=lambda x: -x[2])
        return dupes

    # ------------------------------------------------------------------
    # Composite workflows
    # ------------------------------------------------------------------

    def get_workflows(self, category: Optional[str] = None) -> List[Dict[str, Any]]:
        """Get composite workflow templates."""
        if category:
            return [w for w in COMPOSITE_WORKFLOWS if w.get("category") == category]
        return list(COMPOSITE_WORKFLOWS)

    def resolve_workflow(self, workflow_id: str) -> Optional[Dict[str, Any]]:
        """Resolve a workflow template, validating all referenced presets exist."""
        wf = next((w for w in COMPOSITE_WORKFLOWS if w["id"] == workflow_id), None)
        if not wf:
            return None

        resolved_steps = []
        all_env: Set[str] = set()
        missing_presets = []

        for step in wf["steps"]:
            preset = self._by_id.get(step["preset_id"])
            if not preset:
                missing_presets.append(step["preset_id"])
                continue
            all_env.update(preset.get("required_env", []))
            resolved_steps.append({
                **step,
                "preset_name": preset["name"],
                "preset_tier": preset["tier"],
                "install_cmd": preset.get("install_cmd", ""),
            })

        return {
            **wf,
            "resolved_steps": resolved_steps,
            "missing_presets": missing_presets,
            "all_required_env": sorted(all_env),
            "is_complete": len(missing_presets) == 0,
        }

    # ------------------------------------------------------------------
    # Category intelligence
    # ------------------------------------------------------------------

    def category_report(self, category: str) -> Dict[str, Any]:
        """Deep report on a category including gaps, leaders, and stats."""
        presets = self._by_category.get(category, [])
        if not presets:
            return {"category": category, "error": "not found"}

        tiers = defaultdict(int)
        transports = defaultdict(int)
        total_tools = 0
        all_tags: Dict[str, int] = defaultdict(int)

        for p in presets:
            tiers[p["tier"]] += 1
            transports[p.get("transport", "unknown")] += 1
            total_tools += p.get("tool_count", 0)
            for t in p.get("tags", []):
                all_tags[t] += 1

        leaders = sorted(presets, key=lambda p: (
            -{"official": 3, "vendor": 2, "community": 1}.get(p["tier"], 0),
            p.get("enterprise_priority", 5),
            -p.get("tool_count", 0),
        ))[:5]

        return {
            "category": category,
            "taxonomy": CATEGORY_TAXONOMY.get(category, {}),
            "total_presets": len(presets),
            "total_tools": total_tools,
            "avg_tools_per_preset": round(total_tools / len(presets), 1) if presets else 0,
            "tier_distribution": dict(tiers),
            "transport_distribution": dict(transports),
            "top_tags": dict(sorted(all_tags.items(), key=lambda x: -x[1])[:10]),
            "leaders": [
                {"id": p["id"], "name": p["name"], "tier": p["tier"],
                 "tools": p.get("tool_count", 0), "priority": p.get("enterprise_priority", 5)}
                for p in leaders
            ],
        }

    # ------------------------------------------------------------------
    # Catalog health & stats
    # ------------------------------------------------------------------

    def catalog_health(self) -> Dict[str, Any]:
        """Comprehensive catalog health assessment."""
        total = len(self._catalog)
        no_repo = sum(1 for p in self._catalog if not p.get("repo"))
        no_tags = sum(1 for p in self._catalog if not p.get("tags"))
        low_tools = sum(1 for p in self._catalog if p.get("tool_count", 0) < 3)

        dupes = self.find_duplicates(threshold=0.80)

        categories = {
            cat: len(presets)
            for cat, presets in self._by_category.items()
        }
        thin_categories = {c: n for c, n in categories.items() if n < 3}
        total_tools = sum(p.get("tool_count", 0) for p in self._catalog)

        return {
            "total_presets": total,
            "total_tools": total_tools,
            "total_categories": len(categories),
            "health_score": round(100 * (1 - (no_repo + no_tags + low_tools) / (total * 3)), 1),
            "issues": {
                "missing_repo": no_repo,
                "missing_tags": no_tags,
                "low_tool_count": low_tools,
                "likely_duplicates": len(dupes),
                "thin_categories": thin_categories,
            },
            "top_duplicates": dupes[:10],
            "tier_balance": {
                tier: len(presets) for tier, presets in self._by_tier.items()
            },
        }

    # ------------------------------------------------------------------
    # Generate install script
    # ------------------------------------------------------------------

    def generate_install_script(
        self,
        preset_ids: List[str],
        *,
        shell: str = "bash",
        include_env_template: bool = True,
    ) -> str:
        """Generate a complete install script for a set of presets."""
        stack = self.resolve_stack(preset_ids)
        lines = [
            f"#!/usr/bin/env {shell}",
            "# Auto-generated MCP server install script",
            f"# Presets: {', '.join(preset_ids)}",
            f"# Total: {stack['total_presets']} servers, {stack['total_tools']} tools",
            "",
            "set -euo pipefail",
            "",
        ]

        if include_env_template and stack["required_env_vars"]:
            lines.append("# === Required Environment Variables ===")
            lines.append("# Copy to .env and fill in values:")
            for env in stack["required_env_vars"]:
                lines.append(f'# export {env}=""')
            lines.append("")

        if stack["conflicts"]:
            lines.append("# === WARNINGS ===")
            for c in stack["conflicts"]:
                lines.append(f"# CONFLICT: {' vs '.join(c['presets'])} — {c['reason']}")
            lines.append("")

        for pid in stack["install_order"]:
            p = self._by_id.get(pid)
            if not p:
                continue
            cmd = p.get("install_cmd", "")
            if not cmd:
                continue

            pname = p["name"]
            ptier = p["tier"]
            ptools = p.get("tool_count", 0)
            lines.append(f"# --- {pname} ({ptier}, {ptools} tools) ---")
            lines.append(f"echo 'Installing {pname}...'")
            lines.append(cmd)
            lines.append("")

        return "\n".join(lines)

    # ------------------------------------------------------------------
    # Capability graph & gap analysis
    # ------------------------------------------------------------------

    def capability_providers(self, capability: str) -> List[Dict[str, Any]]:
        """Get all presets that provide a given abstract capability, ranked."""
        cap = CAPABILITY_GRAPH.get(capability)
        if not cap:
            return []

        tier_pref = cap.get("tier_preference", [])
        results = []
        for pid in cap["providers"]:
            preset = self._by_id.get(pid)
            if preset:
                tier_rank = tier_pref.index(preset["tier"]) if preset["tier"] in tier_pref else 99
                results.append({
                    **preset,
                    "_capability": capability,
                    "_tier_rank": tier_rank,
                })
        results.sort(key=lambda x: (x["_tier_rank"], x.get("enterprise_priority", 5)))
        return results

    def list_capabilities(self) -> Dict[str, str]:
        """List all abstract capabilities and their descriptions."""
        return {k: v["description"] for k, v in CAPABILITY_GRAPH.items()}

    def gap_analysis(self, active_preset_ids: List[str]) -> Dict[str, Any]:
        """
        Given currently active presets, identify which abstract capabilities
        are covered and which have gaps (no active provider).
        """
        active_set = set(active_preset_ids)
        covered: Dict[str, List[str]] = {}
        gaps: Dict[str, Dict[str, Any]] = {}

        for cap_name, cap_info in CAPABILITY_GRAPH.items():
            active_providers = [p for p in cap_info["providers"] if p in active_set]
            if active_providers:
                covered[cap_name] = active_providers
            else:
                # Find best recommendation to fill the gap
                best = self.capability_providers(cap_name)
                gaps[cap_name] = {
                    "description": cap_info["description"],
                    "recommended": best[0]["id"] if best else None,
                    "all_providers": cap_info["providers"],
                }

        return {
            "active_presets": sorted(active_set),
            "capabilities_covered": len(covered),
            "capabilities_total": len(CAPABILITY_GRAPH),
            "coverage_pct": round(100 * len(covered) / max(len(CAPABILITY_GRAPH), 1), 1),
            "covered": covered,
            "gaps": gaps,
        }

    # ------------------------------------------------------------------
    # Semantic clustering (k-means on TF-IDF vectors, zero external deps)
    # ------------------------------------------------------------------

    def cluster(self, k: int = 12, max_iter: int = 50, seed: int = 42) -> Dict[str, Any]:
        """
        K-means clustering on TF-IDF vectors to discover natural
        preset groupings beyond manual categories.
        """
        rng = random.Random(seed)
        ids = list(self._tfidf_vectors.keys())
        n = len(ids)
        if n == 0 or k <= 0:
            return {"clusters": [], "k": k}

        all_terms = set()
        for vec in self._tfidf_vectors.values():
            all_terms.update(vec.keys())
        terms = sorted(all_terms)
        term_idx = {t: i for i, t in enumerate(terms)}
        d = len(terms)

        # Build dense-ish matrix (dict-of-index representation)
        vectors: List[Dict[int, float]] = []
        for pid in ids:
            vec = self._tfidf_vectors[pid]
            vectors.append({term_idx[t]: v for t, v in vec.items()})

        # Initialize centroids (k-means++ style)
        centroid_indices = [rng.randint(0, n - 1)]
        for _ in range(1, min(k, n)):
            dists = []
            for i in range(n):
                min_d = float("inf")
                for ci in centroid_indices:
                    dist = self._sparse_dist(vectors[i], vectors[ci])
                    min_d = min(min_d, dist)
                dists.append(min_d)
            total = sum(dists)
            if total == 0:
                break
            probs = [dd / total for dd in dists]
            r = rng.random()
            cumul = 0.0
            for i, p in enumerate(probs):
                cumul += p
                if cumul >= r:
                    centroid_indices.append(i)
                    break

        centroids = [dict(vectors[i]) for i in centroid_indices]
        actual_k = len(centroids)
        assignments = [0] * n

        for _iteration in range(max_iter):
            changed = False
            # Assign
            for i in range(n):
                best_c = 0
                best_d = float("inf")
                for c in range(actual_k):
                    dist = self._sparse_dist(vectors[i], centroids[c])
                    if dist < best_d:
                        best_d = dist
                        best_c = c
                if assignments[i] != best_c:
                    assignments[i] = best_c
                    changed = True

            if not changed:
                break

            # Update centroids
            for c in range(actual_k):
                members = [vectors[i] for i in range(n) if assignments[i] == c]
                if members:
                    new_centroid: Dict[int, float] = defaultdict(float)
                    for m in members:
                        for idx, val in m.items():
                            new_centroid[idx] += val
                    centroids[c] = {idx: val / len(members) for idx, val in new_centroid.items()}

        # Build result
        clusters: List[Dict[str, Any]] = []
        idx_to_term = {i: t for t, i in term_idx.items()}
        for c in range(actual_k):
            member_ids = [ids[i] for i in range(n) if assignments[i] == c]
            if not member_ids:
                continue
            # Top terms for cluster
            top_terms = sorted(centroids[c].items(), key=lambda x: -x[1])[:8]
            clusters.append({
                "cluster_id": c,
                "size": len(member_ids),
                "members": member_ids[:20],
                "total_members": len(member_ids),
                "top_terms": [idx_to_term.get(idx, "?") for idx, _ in top_terms],
                "categories": dict(
                    sorted(
                        defaultdict(
                            int,
                            {
                                self._by_id.get(pid, {}).get("category", "?"): 0
                                for pid in member_ids
                            },
                        ).items(),
                        key=lambda x: -x[1],
                    )
                ),
            })
            # Fix category counts
            cat_counts: Dict[str, int] = defaultdict(int)
            for pid in member_ids:
                cat_counts[self._by_id.get(pid, {}).get("category", "?")] += 1
            clusters[-1]["categories"] = dict(sorted(cat_counts.items(), key=lambda x: -x[1]))

        clusters.sort(key=lambda x: -x["size"])
        return {"clusters": clusters, "k": actual_k, "total_presets": n}

    @staticmethod
    def _sparse_dist(a: Dict[int, float], b: Dict[int, float]) -> float:
        """Euclidean distance between two sparse vectors."""
        keys = set(a.keys()) | set(b.keys())
        return math.sqrt(sum((a.get(k, 0) - b.get(k, 0)) ** 2 for k in keys))

    # ------------------------------------------------------------------
    # Cost optimizer (knapsack-style)
    # ------------------------------------------------------------------

    def optimize_cost(
        self,
        required_capabilities: List[str],
        monthly_budget: float = 1000.0,
        prefer_free: bool = True,
    ) -> Dict[str, Any]:
        """
        Given a set of required capabilities and a budget, find the
        optimal set of presets that covers all capabilities at minimum cost.

        Uses greedy set-cover with cost awareness.
        """
        uncovered = set(required_capabilities)
        selected: List[Dict[str, Any]] = []
        total_cost = 0.0

        while uncovered:
            best_preset = None
            best_covers: Set[str] = set()
            best_score = -1.0

            for cap in list(uncovered):
                providers = self.capability_providers(cap)
                for p in providers:
                    pid = p["id"]
                    if any(s["id"] == pid for s in selected):
                        # Already selected, check if it covers more
                        covers = {c for c in uncovered if pid in CAPABILITY_GRAPH.get(c, {}).get("providers", [])}
                        if covers and len(covers) > len(best_covers):
                            best_covers = covers
                            best_preset = p
                            best_score = len(covers) * 100  # Free since already selected
                        continue

                    # How many uncovered capabilities does this preset cover?
                    covers = {c for c in uncovered if pid in CAPABILITY_GRAPH.get(c, {}).get("providers", [])}
                    if not covers:
                        continue

                    cost = self._estimate_monthly_cost(p)
                    tier_bonus = {"official": 3, "vendor": 2, "community": 1}.get(p["tier"], 0)
                    score = len(covers) * 10 + tier_bonus - (cost / 100.0 if not prefer_free else cost)

                    if score > best_score:
                        best_score = score
                        best_preset = p
                        best_covers = covers

            if best_preset is None:
                break

            if not any(s["id"] == best_preset["id"] for s in selected):
                cost = self._estimate_monthly_cost(best_preset)
                total_cost += cost
                selected.append({
                    "id": best_preset["id"],
                    "name": best_preset["name"],
                    "tier": best_preset["tier"],
                    "estimated_monthly_cost": cost,
                    "covers_capabilities": sorted(best_covers),
                })

            uncovered -= best_covers

        return {
            "selected_presets": selected,
            "total_estimated_monthly_cost": round(total_cost, 2),
            "within_budget": total_cost <= monthly_budget,
            "budget": monthly_budget,
            "capabilities_covered": sorted(set(required_capabilities) - uncovered),
            "capabilities_uncovered": sorted(uncovered),
            "coverage_pct": round(
                100 * (len(required_capabilities) - len(uncovered)) / max(len(required_capabilities), 1), 1
            ),
        }

    @staticmethod
    def _estimate_monthly_cost(preset: Dict[str, Any]) -> float:
        """Heuristic cost estimate based on tier and type."""
        tier = preset.get("tier", "community")
        if tier == "community":
            return 0.0
        elif tier == "official":
            return 0.0
        # Vendor tier
        category = preset.get("category", "")
        if category in ("databases", "analytics", "observability", "security"):
            return 50.0
        if category in ("ai-tools", "data-engineering"):
            return 100.0
        if category in ("finance", "crm", "ecommerce"):
            return 75.0
        return 25.0

    # ------------------------------------------------------------------
    # Migration planner
    # ------------------------------------------------------------------

    def migration_plan(self, from_id: str, to_id: str) -> Optional[Dict[str, Any]]:
        """
        Get a migration plan between two presets, including env mapping,
        breaking changes, and difficulty assessment.
        """
        # Direct path
        for path in MIGRATION_PATHS:
            if path["from"] == from_id and path["to"] == to_id:
                return {**path, "direction": "forward", "steps": self._migration_steps(path)}
            if path["from"] == to_id and path["to"] == from_id:
                reverse = {
                    "from": from_id,
                    "to": to_id,
                    "difficulty": path["difficulty"],
                    "breaking_changes": path["breaking_changes"],
                    "env_mapping": {v: k for k, v in path["env_mapping"].items() if v},
                    "notes": f"Reverse of: {path['notes']}",
                }
                return {**reverse, "direction": "reverse", "steps": self._migration_steps(reverse)}

        # Try to find indirect path via shared capability
        from_preset = self._by_id.get(from_id)
        to_preset = self._by_id.get(to_id)
        if not from_preset or not to_preset:
            return None

        # Check if they share a capability
        from_caps = self._preset_capabilities(from_id)
        to_caps = self._preset_capabilities(to_id)
        shared = from_caps & to_caps

        if shared:
            return {
                "from": from_id,
                "to": to_id,
                "difficulty": "unknown",
                "breaking_changes": ["No known migration path — manual migration required"],
                "env_mapping": {},
                "notes": f"Both provide capabilities: {', '.join(sorted(shared))}. Manual migration needed.",
                "direction": "inferred",
                "shared_capabilities": sorted(shared),
                "steps": [
                    {"step": 1, "action": f"Set up {to_id} alongside {from_id}"},
                    {"step": 2, "action": f"Migrate configuration and data"},
                    {"step": 3, "action": f"Update application to use {to_id}"},
                    {"step": 4, "action": f"Verify functionality"},
                    {"step": 5, "action": f"Decommission {from_id}"},
                ],
            }

        return None

    def _preset_capabilities(self, preset_id: str) -> Set[str]:
        """Get all capabilities a preset provides."""
        caps = set()
        for cap_name, cap_info in CAPABILITY_GRAPH.items():
            if preset_id in cap_info["providers"]:
                caps.add(cap_name)
        return caps

    def _migration_steps(self, path: Dict[str, Any]) -> List[Dict[str, Any]]:
        """Generate migration steps from a migration path."""
        steps = [
            {"step": 1, "action": f"Provision {path['to']} and configure credentials"},
        ]
        if path.get("env_mapping"):
            mappings = [f"{k} → {v}" for k, v in path["env_mapping"].items() if v]
            if mappings:
                steps.append({"step": 2, "action": f"Map env vars: {'; '.join(mappings)}"})
        if path.get("breaking_changes"):
            for i, bc in enumerate(path["breaking_changes"]):
                steps.append({"step": len(steps) + 1, "action": f"Handle breaking change: {bc}"})
        steps.append({"step": len(steps) + 1, "action": f"Run parallel with {path['from']} for validation"})
        steps.append({"step": len(steps) + 1, "action": f"Cut over traffic to {path['to']}"})
        steps.append({"step": len(steps) + 1, "action": f"Decommission {path['from']}"})
        return steps

    def list_migrations(self, preset_id: Optional[str] = None) -> List[Dict[str, Any]]:
        """List available migration paths, optionally filtered by preset."""
        if preset_id:
            return [
                p for p in MIGRATION_PATHS
                if p["from"] == preset_id or p["to"] == preset_id
            ]
        return list(MIGRATION_PATHS)

    # ------------------------------------------------------------------
    # Security posture scoring
    # ------------------------------------------------------------------

    def security_posture(self, preset_ids: List[str]) -> Dict[str, Any]:
        """
        Compute aggregate security posture for a stack of presets.

        Evaluates: transport security, tier trust, auth requirements,
        open-source auditability, and secret surface area.
        """
        if not preset_ids:
            return {"score": 0, "presets": [], "risk_factors": []}

        preset_scores = []
        risk_factors: List[str] = []
        total_secrets = 0

        for pid in preset_ids:
            p = self._by_id.get(pid)
            if not p:
                continue

            score = 0.0
            transport = p.get("transport", "stdio")
            score += SECURITY_WEIGHTS.get(f"transport_{transport}", 0.3)
            score += SECURITY_WEIGHTS.get(f"tier_{p['tier']}", 0.2)

            if p.get("repo"):
                score += SECURITY_WEIGHTS["has_repo"]

            n_secrets = len(p.get("required_env", []))
            total_secrets += n_secrets
            if n_secrets == 0:
                score += SECURITY_WEIGHTS["no_required_env"]
            elif n_secrets > 0:
                score += SECURITY_WEIGHTS["has_auth"]

            # Risk detection
            if p["tier"] == "community" and not p.get("repo"):
                risk_factors.append(f"{pid}: community tier with no public repo (unauditable)")
            if n_secrets > 3:
                risk_factors.append(f"{pid}: requires {n_secrets} secrets (large attack surface)")
            if transport == "sse" and p["tier"] == "community":
                risk_factors.append(f"{pid}: SSE transport from community source (verify origin)")

            normalized = min(round(score * 50, 1), 100)
            preset_scores.append({
                "id": pid,
                "name": p["name"],
                "score": normalized,
                "transport": transport,
                "tier": p["tier"],
                "secrets_count": n_secrets,
                "has_repo": bool(p.get("repo")),
            })

        avg_score = round(sum(ps["score"] for ps in preset_scores) / max(len(preset_scores), 1), 1)

        # Deductions
        if total_secrets > 15:
            avg_score = max(0, avg_score - 10)
            risk_factors.append(f"High total secret count ({total_secrets}) increases credential management risk")

        community_pct = sum(1 for ps in preset_scores if ps["tier"] == "community") / max(len(preset_scores), 1)
        if community_pct > 0.6:
            avg_score = max(0, avg_score - 5)
            risk_factors.append(f"{community_pct:.0%} of stack is community-tier (limited security guarantees)")

        return {
            "aggregate_score": avg_score,
            "grade": "A" if avg_score >= 80 else "B" if avg_score >= 60 else "C" if avg_score >= 40 else "D",
            "total_secrets": total_secrets,
            "risk_factors": risk_factors,
            "preset_scores": sorted(preset_scores, key=lambda x: -x["score"]),
        }

    # ------------------------------------------------------------------
    # Collaborative filtering — "users who activated X also activated Y"
    # ------------------------------------------------------------------

    def coactivation_recommend(
        self,
        active_preset_ids: List[str],
        limit: int = 10,
    ) -> List[Dict[str, Any]]:
        """
        Collaborative filtering: given currently active presets,
        recommend others that are commonly co-activated.
        """
        active_set = set(active_preset_ids)
        candidate_scores: Dict[str, float] = defaultdict(float)

        for pid in active_preset_ids:
            coactivated = COACTIVATION_MATRIX.get(pid, [])
            for co_pid in coactivated:
                if co_pid not in active_set and co_pid in self._by_id:
                    # Score based on how many active presets recommend this
                    candidate_scores[co_pid] += 1.0

        # Boost by tier
        results = []
        for pid, raw_score in candidate_scores.items():
            preset = self._by_id[pid]
            tier_boost = {"official": 1.3, "vendor": 1.15, "community": 1.0}.get(preset["tier"], 1.0)
            final_score = raw_score * tier_boost
            results.append({
                **preset,
                "_coactivation_score": round(final_score, 2),
                "_raw_mentions": int(raw_score),
                "_reason": f"Co-activated with {int(raw_score)} of your active presets",
            })

        results.sort(key=lambda x: -x["_coactivation_score"])
        return results[:limit]

    # ------------------------------------------------------------------
    # Stack comparison
    # ------------------------------------------------------------------

    def compare_stacks(
        self,
        stack_a: List[str],
        stack_b: List[str],
    ) -> Dict[str, Any]:
        """
        Compare two stacks of presets across multiple dimensions:
        tools, cost, security, capability coverage.
        """
        def _stack_stats(ids: List[str]) -> Dict[str, Any]:
            presets = [self._by_id[pid] for pid in ids if pid in self._by_id]
            total_tools = sum(p.get("tool_count", 0) for p in presets)
            total_cost = sum(self._estimate_monthly_cost(p) for p in presets)
            caps = set()
            for pid in ids:
                caps.update(self._preset_capabilities(pid))
            sec = self.security_posture(ids)
            return {
                "preset_count": len(presets),
                "total_tools": total_tools,
                "estimated_monthly_cost": round(total_cost, 2),
                "capabilities": sorted(caps),
                "capability_count": len(caps),
                "security_score": sec["aggregate_score"],
                "security_grade": sec["grade"],
                "tier_mix": {
                    tier: sum(1 for p in presets if p["tier"] == tier)
                    for tier in ["official", "vendor", "community"]
                    if any(p["tier"] == tier for p in presets)
                },
            }

        a_stats = _stack_stats(stack_a)
        b_stats = _stack_stats(stack_b)

        a_caps = set(a_stats["capabilities"])
        b_caps = set(b_stats["capabilities"])

        return {
            "stack_a": {"preset_ids": stack_a, **a_stats},
            "stack_b": {"preset_ids": stack_b, **b_stats},
            "comparison": {
                "tool_advantage": "A" if a_stats["total_tools"] > b_stats["total_tools"] else "B",
                "cost_advantage": "A" if a_stats["estimated_monthly_cost"] < b_stats["estimated_monthly_cost"] else "B",
                "security_advantage": "A" if a_stats["security_score"] > b_stats["security_score"] else "B",
                "capability_advantage": "A" if a_stats["capability_count"] > b_stats["capability_count"] else "B",
                "capabilities_only_in_a": sorted(a_caps - b_caps),
                "capabilities_only_in_b": sorted(b_caps - a_caps),
                "shared_capabilities": sorted(a_caps & b_caps),
            },
        }

    # ------------------------------------------------------------------
    # Preset evolution — diff two versions of a preset
    # ------------------------------------------------------------------

    def preset_alternatives(self, preset_id: str) -> Dict[str, Any]:
        """
        Find all alternatives for a preset: similar presets, migration paths,
        capability equivalents, and co-activation suggestions.
        """
        if not self._by_id.get(preset_id):
            return {"error": "not found"}

        similar = self.find_similar(preset_id, limit=5)
        migrations = self.list_migrations(preset_id)
        caps = self._preset_capabilities(preset_id)
        cap_alternatives: Dict[str, List[str]] = {}
        for cap in caps:
            providers = [p["id"] for p in self.capability_providers(cap) if p["id"] != preset_id]
            if providers:
                cap_alternatives[cap] = providers[:3]

        return {
            "preset_id": preset_id,
            "similar_presets": [
                {"id": p["id"], "name": p["name"], "similarity": round(s, 3)}
                for p, s in similar
            ],
            "migration_paths": migrations,
            "capability_alternatives": cap_alternatives,
            "capabilities": sorted(caps),
        }


# ============================================================================
# Backward-compatible module-level functions (used by preset_routes.py)
# ============================================================================

_engine: Optional[CatalogEngine] = None


def _get_engine() -> CatalogEngine:
    global _engine
    if _engine is None:
        _engine = CatalogEngine()
    return _engine


def get_presets_by_category(category: str) -> List[Dict[str, Any]]:
    """Get all presets in a category."""
    return _get_engine().get_by_category(category)


def get_presets_by_tag(tag: str) -> List[Dict[str, Any]]:
    """Get all presets with a given tag."""
    return _get_engine().get_by_tag(tag)


def get_presets_by_tier(tier: str) -> List[Dict[str, Any]]:
    """Get all presets at a given tier (official, vendor, community)."""
    return _get_engine().get_by_tier(tier)


def get_preset_by_id(preset_id: str) -> Optional[Dict[str, Any]]:
    """Get a specific preset by ID."""
    return _get_engine().get_by_id(preset_id)


def get_all_categories() -> Dict[str, int]:
    """Get all categories with counts."""
    cats: Dict[str, int] = {}
    for p in PRESET_CATALOG:
        cat = p["category"]
        cats[cat] = cats.get(cat, 0) + 1
    return dict(sorted(cats.items(), key=lambda x: -x[1]))


def get_total_tool_count() -> int:
    """Get approximate total tools across all presets."""
    return sum(p.get("tool_count", 0) for p in PRESET_CATALOG)


def get_catalog_summary() -> Dict[str, Any]:
    """Get a summary of the catalog."""
    categories = get_all_categories()
    tiers: Dict[str, int] = {}
    for p in PRESET_CATALOG:
        t = p["tier"]
        tiers[t] = tiers.get(t, 0) + 1

    return {
        "total_integrations": len(PRESET_CATALOG),
        "total_tools": get_total_tool_count(),
        "categories": categories,
        "tiers": tiers,
        "enterprise_critical": len([p for p in PRESET_CATALOG if p["enterprise_priority"] == 1]),
    }
